#include <vector>
#include <deque>

class Solution {
public:
    long long countSubarrays(std::vector<int>& nums, int k) {
        std::deque<int> min_q, max_q;
        long long ans = 0;
        int left = 0;
        for (int right = 0; right < (int)nums.size(); ++right) {
            int val = nums[right];
            while (!min_q.empty() && min_q.back() > val) min_q.pop_back();
            min_q.push_back(val);
            while (!max_q.empty() && max_q.back() < val) max_q.pop_back();
            max_q.push_back(val);
            while (max_q.front() - min_q.front() > k) {
                if (min_q.front() == nums[left]) min_q.pop_front();
                if (max_q.front() == nums[left]) max_q.pop_front();
                left++;
            }
            ans += (right - left + 1);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long countSubarrays(int[] nums, int k) {
        ArrayDeque<Integer> minQ = new ArrayDeque<>();
        ArrayDeque<Integer> maxQ = new ArrayDeque<>();
        long ans = 0;
        int left = 0;
        for (int right = 0; right < nums.length; right++) {
            int val = nums[right];
            while (!minQ.isEmpty() && minQ.peekLast() > val) minQ.pollLast();
            minQ.addLast(val);
            while (!maxQ.isEmpty() && maxQ.peekLast() < val) maxQ.pollLast();
            maxQ.addLast(val);
            while (maxQ.peekFirst() - minQ.peekFirst() > k) {
                if (minQ.peekFirst() == nums[left]) minQ.pollFirst();
                if (maxQ.peekFirst() == nums[left]) maxQ.pollFirst();
                left++;
            }
            ans += (right - left + 1);
        }
        return ans;
    }
}

function countSubarrays(nums, k) {
    const minQ = [];
    const maxQ = [];
    let ans = 0;
    let left = 0;
    for (let right = 0; right < nums.length; right++) {
        const val = nums[right];
        while (minQ.length > 0 && minQ[minQ.length - 1] > val) minQ.pop();
        minQ.push(val);
        while (maxQ.length > 0 && maxQ[maxQ.length - 1] < val) maxQ.pop();
        maxQ.push(val);
        while (maxQ[0] - minQ[0] > k) {
            if (minQ[0] === nums[left]) minQ.shift();
            if (maxQ[0] === nums[left]) maxQ.shift();
            left++;
        }
        ans += (right - left + 1);
    }
    return ans;
